def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    last_my, last_opp = history[-1]

    opp_d = 0
    my_d = 0
    after_d_c = 0
    after_d_d = 0
    after_c_c = 0
    after_c_d = 0

    trans = [[[0, 0] for _ in range(2)] for __ in range(2)]

    for i in range(n):
        a, b = history[i]
        if b == 'D':
            opp_d += 1
        if a == 'D':
            my_d += 1

        if i > 0:
            pa, pb = history[i - 1]

            if pa == 'D':
                if b == 'C':
                    after_d_c += 1
                else:
                    after_d_d += 1
            else:
                if b == 'C':
                    after_c_c += 1
                else:
                    after_c_d += 1

            mi = 0 if pa == 'C' else 1
            pi = 0 if pb == 'C' else 1
            bi = 0 if b == 'C' else 1
            trans[mi][pi][bi] += 1

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    win = n if n < 20 else 20
    opp_d_recent = 0
    for i in range(n - win, n):
        if history[i][1] == 'D':
            opp_d_recent += 1

    if n >= 99:
        return 'D'

    if opp_d >= 5 and opp_d * 4 > n * 3:
        return 'D'

    if win >= 8 and opp_d_recent >= win and opp_d * 2 > n:
        return 'D'

    exploit = False
    if opp_d == 0 and after_d_c >= 1:
        exploit = True
    elif after_d_c >= 3 and after_d_c * 2 > after_d_d * 3 and opp_d * 20 < n * 13 and after_c_d <= after_c_c:
        exploit = True
    elif after_d_c >= 2 and after_d_c > after_d_d * 2 and opp_d * 5 < n * 2 and after_c_d <= after_c_c:
        exploit = True

    if last_my == 'D' and last_opp == 'C':
        if exploit:
            return 'D'

        cnt_c = trans[1][0][0]
        cnt_d = trans[1][0][1]
        total = cnt_c + cnt_d

        if total >= 5 and cnt_c * 2 >= cnt_d:
            return 'D'

        if total == 0:
            if opp_d * 5 > n * 3:
                return 'D'
            return 'C'

        if cnt_c * 2 < cnt_d:
            if opp_d * 5 > n * 3:
                return 'D'
            return 'C'

        return 'C'

    if last_opp == 'D':
        k = n - opp_d_streak
        provoked = k > 0 and history[k - 1][0] == 'D'

        if provoked:
            if opp_d * 20 < n * 7:
                if opp_d_streak <= 4:
                    return 'C'
                if rng.random() < 0.35:
                    return 'C'
                return 'D'
            elif opp_d * 5 < n * 3:
                if opp_d_streak <= 2:
                    return 'C'
                if opp_d_streak >= 4 and rng.random() < 0.15:
                    return 'C'
                return 'D'
            return 'D'

        else:
            if opp_d * 20 < n * 7:
                if opp_d_streak == 1:
                    return 'D'
                if opp_d_streak == 2:
                    if rng.random() < 0.30:
                        return 'C'
                    return 'D'
                if rng.random() < 0.45:
                    return 'C'
                return 'D'
            elif opp_d * 5 < n * 3:
                if opp_d_streak >= 3 and rng.random() < 0.20:
                    return 'C'
                return 'D'
            return 'D'

    if exploit:
        return 'D'

    if n >= 18 and my_d > 0 and last_my == 'C':
        tot_c = after_c_c + after_c_d
        tot_d = after_d_c + after_d_d

        if tot_c >= 8 and tot_d >= 8:
            pc_c = after_c_c / float(tot_c)
            pc_d = after_d_c / float(tot_d)

            if pc_c - pc_d <= 0.18 and opp_d * 4 < n * 3:
                return 'D'

    if my_d == 0 and opp_d == 0 and last_opp == 'C':
        if n >= 95:
            return 'D'

        if n >= 6:
            prob = 0.20 + (n - 6) * 0.015
            if prob > 0.90:
                prob = 0.90
            if rng.random() < prob:
                return 'D'

        return 'C'

    if my_d == 0:
        return 'C'

    if opp_d * 10 > n * 7:
        return 'D'

    return 'C'
